import copy
import math


class TimingLedger:
    def __init__(self):
        self._records = []

    @staticmethod
    def _text(value, name):
        if not isinstance(value, str):
            raise TypeError(name + " must be a string")
        if not value:
            raise ValueError(name + " must not be empty")

    def add(self, operation, engine, data_type, size, duration):
        self._text(operation, "operation")
        self._text(engine, "engine")
        self._text(data_type, "data_type")
        if isinstance(size, bool) or not isinstance(size, int):
            raise TypeError("size must be an integer")
        if size <= 0:
            raise ValueError("size must be positive")
        if isinstance(duration, bool) or not isinstance(duration, (int, float)):
            raise TypeError("duration must be numeric")
        if not math.isfinite(duration) or duration < 0:
            raise ValueError("duration must be finite and non-negative")
        self._records.append({
            "operation": operation,
            "engine": engine,
            "data_type": data_type,
            "size": size,
            "duration": float(duration),
        })

    def snapshot(self):
        return self._records

    def _groups(self):
        groups = {}
        for record in self._records:
            key = (record["operation"], record["engine"], record["data_type"], record["size"])
            groups.setdefault(key, []).append(record["duration"])
        return groups

    def csv_report(self):
        rows = ["operation,engine,data_type,size,count,average"]
        for key, values in sorted(self._groups().items()):
            rows.append(",".join((key[0], key[1], key[2], str(key[3]), str(len(values)), f"{sum(values) / len(values):.6f}")))
        return "\n".join(rows)

    def comparison_series(self, operation, data_type, first_engine, second_engine):
        for value, name in ((operation, "operation"), (data_type, "data_type"),
                            (first_engine, "first_engine"), (second_engine, "second_engine")):
            self._text(value, name)
        averages = {}
        for key, values in self._groups().items():
            op, engine, dtype, size = key
            if op == operation and dtype == data_type and engine in (first_engine, second_engine):
                averages[(engine, size)] = sum(values) / len(values)
        sizes = sorted({size for engine, size in averages if
                        (first_engine, size) in averages and (second_engine, size) in averages})
        return [{
            "size": size,
            "first_average": averages[(first_engine, size)],
            "second_average": averages[(second_engine, size)],
            "ratio": (averages[(first_engine, size)] / averages[(second_engine, size)]
                      if averages[(second_engine, size)] != 0 else None),
        } for size in sizes]

